const animal = {
  emiteSom() {
    return `${this.nome} faz um som genérico`;
  }
};

const cao = Object.create(animal);
cao.nome = "Rex";

console.log(cao.emiteSom());                   // "Rex faz um som genérico" (herdado de animal)
console.log(cao.hasOwnProperty("nome"));       // true, propriedade própria
console.log(cao.hasOwnProperty("emiteSom"));   // false, vem da cadeia de protótipos
console.log(Object.getPrototypeOf(cao) === animal); // true

// no topo da cadeia está sempre Object.prototype, e a seguir null
console.log(Object.getPrototypeOf(Object.getPrototypeOf(cao)) === Object.prototype); // true
console.log(Object.getPrototypeOf(Object.prototype)); // null

const base = { saudacao: "Olá" };
const objeto = Object.create(base);

console.log(Object.getPrototypeOf(objeto) === base); // true
console.log(base.isPrototypeOf(objeto));             // true

const outraBase = { saudacao: "Bom dia" };
Object.setPrototypeOf(objeto, outraBase);

console.log(objeto.saudacao); // "Bom dia" — a cadeia foi trocada em runtime

const contadorBase = {
  valor: 0,
  incrementar() {
    this.valor += 1;
    return this.valor;
  }
};

const contadorA = Object.create(contadorBase);
const contadorB = Object.create(contadorBase);

contadorA.incrementar();
contadorA.incrementar();
contadorB.incrementar();

console.log(contadorA.valor);    // 2 — propriedade própria criada na primeira escrita
console.log(contadorB.valor);    // 1
console.log(contadorBase.valor); // 0, nunca foi alterado

// objeto sem protótipo nenhum, útil como "dicionário puro"
const dicionario = Object.create(null);
dicionario.chave = "valor";
console.log(dicionario.toString); // undefined, não herda nada de Object.prototype

function Pessoa(nome, idade) {
  this.nome = nome;
  this.idade = idade;
}

// métodos definem-se no prototype, não dentro do construtor:
Pessoa.prototype.apresentar = function () {
  return `Sou ${this.nome} e tenho ${this.idade} anos`;
};

const ana = new Pessoa("Ana", 30);
const rui = new Pessoa("Rui", 42);

console.log(ana.apresentar());                  // "Sou Ana e tenho 30 anos"
console.log(ana.apresentar === rui.apresentar); // true — o método é partilhado, não duplicado
console.log(ana instanceof Pessoa);             // true
console.log(Object.getPrototypeOf(ana) === Pessoa.prototype); // true

function Animal(nome) {
  this.nome = nome;
}

Animal.prototype.emiteSom = function () {
  return `${this.nome} faz um som`;
};

function Cao(nome, raca) {
  Animal.call(this, nome);   // chama o "construtor pai" com o this correto
  this.raca = raca;
}

// liga a cadeia: Cao.prototype passa a herdar de Animal.prototype
Cao.prototype = Object.create(Animal.prototype);
Cao.prototype.constructor = Cao; // repõe a referência que Object.create apagou

Cao.prototype.latir = function () {
  return `${this.nome} ladra: Woof!`;
};

const bobi = new Cao("Bobi", "Labrador");

console.log(bobi.emiteSom());        // "Bobi faz um som" (herdado de Animal.prototype)
console.log(bobi.latir());           // "Bobi ladra: Woof!" (próprio de Cao.prototype)
console.log(bobi instanceof Cao);    // true
console.log(bobi instanceof Animal); // true, porque a cadeia liga os dois prototypes

function meuNew(Construtor, ...args) {
  // 1. cria um objeto cujo protótipo é Construtor.prototype
  const instancia = Object.create(Construtor.prototype);

  // 2. executa o construtor com "this" a apontar para essa instância
  const resultado = Construtor.apply(instancia, args);

  // 3. só um objeto devolvido explicitamente substitui a instância criada
  return (typeof resultado === "object" && resultado !== null) ? resultado : instancia;
}

function Ponto(x, y) {
  this.x = x;
  this.y = y;
}

const p1 = new Ponto(2, 3);
const p2 = meuNew(Ponto, 2, 3);

console.log(p2.x, p2.y);                                // 2 3
console.log(p2 instanceof Ponto);                       // true
console.log(JSON.stringify(p1) === JSON.stringify(p2)); // true

