const veiculo = {
  descrever() {
    return `Este veículo tem ${this.rodas} rodas`;
  }
};

const carro = Object.create(veiculo);
carro.rodas = 4;

console.log(Object.getPrototypeOf(carro) === veiculo); // true
console.log(carro.descrever()); // "Este veículo tem 4 rodas"

function Produto(nome, preco) {
  this.nome = nome;
  this.preco = preco;
}

Produto.prototype.aplicarDesconto = function (percentagem) {
  return this.preco * (1 - percentagem / 100);
};

const p1 = new Produto("Teclado", 50);
const p2 = new Produto("Rato", 20);

console.log(p1.aplicarDesconto(10)); // 45
console.log(p2.aplicarDesconto(25)); // 15
console.log(p1.aplicarDesconto === p2.aplicarDesconto); // true

function FormaGeometrica(cor) {
  this.cor = cor;
}

FormaGeometrica.prototype.descreverCor = function () {
  return `Cor: ${this.cor}`;
};

function Circulo(cor, raio) {
  FormaGeometrica.call(this, cor);
  this.raio = raio;
}

Circulo.prototype = Object.create(FormaGeometrica.prototype);
Circulo.prototype.constructor = Circulo;

Circulo.prototype.calcularArea = function () {
  return Math.PI * this.raio ** 2;
};

const c = new Circulo("vermelho", 3);

console.log(c.descreverCor());            // "Cor: vermelho"
console.log(c.calcularArea().toFixed(2)); // "28.27"
console.log(c instanceof Circulo);        // true
console.log(c instanceof FormaGeometrica); // true

function meuNew(Construtor, ...args) {
  const instancia = Object.create(Construtor.prototype);
  const resultado = Construtor.apply(instancia, args);
  return (typeof resultado === "object" && resultado !== null) ? resultado : instancia;
}

function Pessoa(nome) {
  this.nome = nome;
}

const p1 = new Pessoa("Inês");
const p2 = meuNew(Pessoa, "Inês");

console.log(p2.nome);              // "Inês"
console.log(p2 instanceof Pessoa); // true
console.log(Object.getPrototypeOf(p1) === Object.getPrototypeOf(p2)); // true
